<script setup>
import {ref} from 'vue';import {cart,cartTotal} from '../../stores';import api from '../../services/api';import {useRouter} from 'vue-router'
const router=useRouter(),address=ref(''),affiliateCode=ref(''),loading=ref(false),error=ref('')
async function submit(){if(!cart.items.length||!address.value)return;loading.value=true;error.value='';try{const r=await api.post('/orders',{affiliateCode:affiliateCode.value||undefined,shippingAddress:{address:address.value}});cart.items=[];router.push('/orders')}catch(e){error.value=e.response?.data?.message||'Unable to create order.'}finally{loading.value=false}}
</script><template><section class="mx-auto max-w-3xl"><h1 class="text-3xl font-black">Checkout</h1><div class="mt-8 rounded-2xl border bg-white p-6"><label class="text-sm font-bold">Shipping address</label><textarea v-model="address" rows="4" class="mt-2 w-full rounded-xl border p-3" placeholder="Full delivery address"></textarea><label class="mt-5 block text-sm font-bold">Affiliate code (optional)</label><input v-model="affiliateCode" class="mt-2 w-full rounded-xl border p-3" placeholder="AFF-..."/><p v-if="error" class="mt-4 text-sm text-red-600">{{error}}</p><div class="mt-6 flex items-center justify-between border-t pt-5"><b>Total</b><b class="text-xl">{{cartTotal.toLocaleString()}} ETB</b></div><button :disabled="loading" @click="submit" class="mt-5 w-full rounded-xl bg-indigo-600 py-3 font-bold text-white disabled:opacity-50">{{loading?'Creating…':'Place order'}}</button></div></section></template>